style.css:
@-moz-document domain("egy-uae.online") {
/* إعدادات الجسم (Body) */
    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }

    body {
        font-family: 'Arial', sans-serif;
        background-color: #f4f4f4;
        color: #333;
    }

    /* تنسيق العناوين */
    h1, h2, h3 {
        font-family: 'Verdana', sans-serif;
        color: #333;
        margin-bottom: 20px;
    }

    /* تصميم التنقل (Navigation Bar) */
    .navbar {
        background-color: #004d7a;
        padding: 10px 20px;
        position: fixed;
        width: 100%;
        top: 0;
        z-index: 1000;
    }

    .navbar a {
        color: #fff;
        text-decoration: none;
        padding: 10px 15px;
        margin: 0 10px;
        transition: background-color 0.3s;
    }

    .navbar a:hover {
        background-color: #005b8b;
    }

    /* تصميم الأزرار */
    button {
        background-color: #007bff;
        border: none;
        color: white;
        padding: 12px 20px;
        text-align: center;
        text-decoration: none;
        display: inline-block;
        font-size: 16px;
        cursor: pointer;
        border-radius: 5px;
        transition: background-color 0.3s;
    }

    button:hover {
        background-color: #0056b3;
    }

    /* تصميم الجداول */
    table {
        width: 100%;
        margin: 20px 0;
        border-collapse: collapse;
    }

    table, th, td {
        border: 1px solid #ddd;
    }

    th, td {
        padding: 12px;
        text-align: center;
    }

    th {
        background-color: #004d7a;
        color: #fff;
    }

    tr:nth-child(even) {
        background-color: #f2f2f2;
    }

    tr:hover {
        background-color: #ddd;
    }

    /* تصميم الصور */
    img {
        max-width: 100%;
        height: auto;
        border-radius: 10px;
    }

    /* تصميم الحاويات */
    .container {
        width: 90%;
        margin: 0 auto;
        padding: 20px;
    }

    /* تصميم الأقسام */
    .section {
        margin-bottom: 40px;
    }

    .section-title {
        font-size: 24px;
        font-weight: bold;
        color: #004d7a;
    }

    /* تصميم التذييل (Footer) */
    footer {
        background-color: #004d7a;
        color: #fff;
        text-align: center;
        padding: 20px 0;
        position: relative;
        bottom: 0;
        width: 100%;
    }

    /* تأثيرات الانتقال (Transitions) */
    a, button {
        transition: background-color 0.3s, transform 0.3s;
    }

    a:hover, button:hover {
        transform: scale(1.05);
    }

    /* التصميم المتجاوب (Responsive Design) */
    @media (max-width: 768px) {
        .navbar {
            padding: 15px;
        }
        
        .container {
            width: 100%;
            padding: 10px;
        }

        .section-title {
            font-size: 20px;
        }
    }

    /* تصميم للشاشة الصغيرة (مثل الجوال) */
    @media (max-width: 480px) {
        .navbar a {
            padding: 8px 12px;
            font-size: 14px;
        }

        .section-title {
            font-size: 18px;
        }

        footer {
            font-size: 14px;
        }
    }
}
